local _, ns = ...
ns.data = {
  client = "forever",
  sections = {
    { id = "beasts", title = "Beasts", type = "Beast" },
    { id = "dragonkin", title = "Dragonkin", type = "Dragonkin" },
    { id = "demons", title = "Demons", type = "Demon" },
    { id = "elementals", title = "Elementals", type = "Elemental" },
    { id = "undead", title = "The Undead", type = "Undead" },
    { id = "giants", title = "Giants", type = "Giant" },
    { id = "machines", title = "Machines", type = "Mechanical" },
    { id = "peoples", title = "Humanoids", type = "Humanoid" },
    { id = "oddities", title = "Oddities", type = "NotSpecified" },
  },
  families = {
    { id = "wolves", title = "Wolves", section = "beasts", note = { "A howl can make a whole forest seem inhabited. Wolves live from Dun Morogh's snowfields to Elwynn's timber, and their different coats belong as naturally to those places as the trees do. The larger worgs give the familiar outline a heavier jaw.", "Orcs have brought wolves into their lives as companions and mounts; young hunters meet the wild packs on a very different footing. Hunger is particularly visible in the starving wolves near settled roads. The distance between wilderness and a village is sometimes a very short one." } },
    { id = "great-cats", title = "Great Cats", section = "beasts", note = { "The great cats give a forest much of its silence. A nightsaber's dark coat disappears among Teldrassil's trees, a frostsaber belongs to the snow of Winterspring, and a Stranglethorn panther can be remarkably difficult to pick out in plain daylight.", "The night elves' bond with their sabers shows another side of these hunters: companions and mounts as well as predators. Beyond the trained animals, the same grace serves the business of hunting. A tiger crossing a sunlit path is a fine sight, however briefly it lasts." } },
    { id = "spiders", title = "Spiders", section = "beasts", note = { "Webs divide a cave into a space a traveller can see and a space already occupied. In Elwynn's mines and Teldrassil's Webwood, the spiders themselves are often large enough to explain why a familiar path has fallen quiet.", "Venom sacs and silk bring them to the attention of apothecaries and craftsfolk. The silk is a particularly fine material to find stretched across an abandoned doorway. Its maker has no need of a loom, and no interest in the uses to which the finished work will be put." } },
    { id = "bears", title = "Bears", section = "beasts", note = { "From the black bears of Khaz Modan to the white shardtooths of Winterspring, bears make a forest seem well occupied even when little else is visible. A broad back among the trees, a heavy paw on the path, and the undergrowth suddenly feels less empty.", "Their strength has earned them a place in the druids' arts as well as in hunters' stories. For a bear, however, the immediate business is its own: food, territory, and whatever has just wandered too close. It is quite possible to admire one without becoming part of that business." } },
    { id = "boars", title = "Boars", section = "beasts", note = { "Boars turn up in the red gullies of Durotar as readily as in Elwynn's green fields. The colouring changes, and a crag boar has a fine coat against the snow, but the tusks give the same unmistakable outline.", "Westfall's goretusks are a nuisance to the farms and a useful supply of meat. This leaves the boar in the unfortunate position of being wanted out of a field and into a cooking pot, often by the same person. It generally objects to both." } },
    { id = "crocolisks", title = "Crocolisks", section = "beasts", note = { "Crocolisks are ancient things, long-jawed and armoured, which have outlasted empires by the simple method of lying still in warm water and eating whatever comes to drink. They haunt the lochs of Khaz Modan, the bogs of the Wetlands, the rivers of Stranglethorn and the shores of Dustwallow.", "A crocolisk on the bank looks asleep. It is not. It can cover the distance to a careless traveller faster than seems decent for something so heavy.", "Their hides make fine leather, and their meat is better than it has any right to be. Neither is worth losing a leg over." } },
    { id = "carrion-birds", title = "Carrion Birds", section = "beasts", note = { "The carrion birds are the patient ones: vultures, buzzards and condors circling over the Barrens, the Badlands and the Thousand Needles, waiting for the land to do their killing for them. The fleshrippers of Westfall have grown bolder since the farms emptied, and will not always wait.", "They are a sign worth reading. A ring of them in the sky means something below has died or is about to, and sometimes it is wise to find out what before you walk into it.", "The rocs of the far south are another matter: great birds of prey that hunt living game, and treat a traveller as such." } },
    { id = "crabs", title = "Crabs", section = "beasts", note = { "A crab carries a little fortress along the shore. The shell covers most of the argument, the claws settle the rest, and the whole arrangement moves sideways with admirable assurance.", "Sand crawlers and surf crawlers occupy beaches across both continents. Cooks value their meat, while an undisturbed stretch of sand gives a naturalist something worth watching: a creature going about its affairs at the boundary between land and sea. Not everything on a beach is waiting for a ship." } },
    { id = "gorillas", title = "Gorillas", section = "beasts", note = { "The gorillas of Stranglethorn, Feralas and Un'Goro have the bulk to be noticed in a crowded jungle. Silverbacks, mistvale apes and the great thunderers differ in size, but even the smaller ones make the tree trunks around them look slender.", "The names tell something of the impression they leave: King Mukla, Uhk'loc, U'cha. Hunters go looking for a particular beast and come back with a name that sounds like a ruler's. A gorilla needs neither crown nor throne to occupy a clearing very thoroughly." } },
    { id = "raptors", title = "Raptors", section = "beasts", note = { "A raptor is all hind legs, tail and teeth, built along lines quite unlike a wolf or cat. The bloodtalons of Durotar and the sunscales of the Barrens are familiar examples; larger kinds hunt through the Wetlands and the southern jungles.", "Troll riders have made companions of them, a practice that requires great confidence in the animal at one's back. In the wild, a raptor's narrow outline can be lost among reeds until it turns. The head is usually the first part a traveller remembers." } },
    { id = "tallstriders", title = "Tallstriders", section = "beasts", note = { "The tallstriders are long-legged, long-necked birds of the open plains, and the plainstriders of Mulgore and the Barrens are the most familiar sight of the grasslands after the kodo. They are harmless enough until cornered, and then they kick hard enough to break a shield.", "The tauren hunt them for their meat and feathers, with the thanks the Earth Mother asks of them; the night elves of Darkshore and Felwood know a forest cousin, the foreststrider.", "Their eggs are prized. Their mothers are aware of this." } },
    { id = "scorpids", title = "Scorpids", section = "beasts", note = { "Scorpids make remarkably good use of dry ground. Their low shells blend with Durotar's red earth and the dust of the southern deserts, while the lifted tail is visible a disconcerting moment later.", "Their venom and armour both have uses, which sends young hunters looking for creatures their elders have warned them about. The orcs of Durotar know scorpid shells well. A specimen laid out for study is a handsome piece of natural armour, with joints that repay a close look." } },
    { id = "turtles", title = "Turtles", section = "beasts", note = { "A turtle's shell makes the rest of the creature seem an afterthought until the head emerges. Snapjaws inhabit lakes and rivers; the large coastal turtles of Tanaris and Azshara carry the same sturdy design into salt water.", "Their patience is easy to admire from the bank. Up close, the beak deserves equal study. Between the two sits an animal remarkably well equipped to occupy a stretch of water without appearing to exert itself." } },
    { id = "bats", title = "Bats", section = "beasts", note = { "A cave that looks empty by daylight may have a ceiling full of bats. Duskbats hang over the paths of Tirisfal, while the thorny passages of Razorfen shelter their own colonies. Wings fill a surprisingly large part of a narrow tunnel.", "The plaguebats of the eastern lands belong in a less cheerful account. Disease travels with them through country already ruined by the Scourge. A bat's shape is familiar; what it carries depends very much on where it has been roosting." } },
    { id = "hyenas", title = "Hyenas", section = "beasts", note = { "Hyenas suit the dry country: lean shapes against the dust of the Barrens, Tanaris and Desolace. Their calls give them away even when the grass or a fold in the ground hides the pack.", "The names bestowed on them are seldom affectionate. Snickerfang, blisterpaw, starving hyena: travellers remember the sound, the teeth or the condition of the beast that followed them. There is a whole difficult life in that last name, out where a meal is never assured." } },
    { id = "owls", title = "Owls", section = "beasts", note = { "An owl is often easiest to find by its eyes. The strigids of Teldrassil sit within a forest already full of night elf watchfulness, while Winterspring's great owls stand out pale against the dark trees.", "Felwood's ironbeaks belong to a damaged woodland, and share in its dangers. Elsewhere, there is room to appreciate the stillness of a perched bird before the wings open. The forests contain quite enough noise; an owl makes an excellent study in its absence." } },
    { id = "wind-serpents", title = "Wind Serpents", section = "beasts", note = { "Wind serpents draw long, bright shapes across the skies of the Barrens and Thousand Needles. Feathered wings carry a body that seems made for the ground, and lightning supplies a further reason to reconsider appearances.", "Some trolls revere winged serpents, and darker examples have a place among Hakkar's followers. The wild creatures remain striking in their own right. Against a bare cliff, a wind serpent can provide nearly all the colour in the view." } },
    { id = "basilisks", title = "Basilisks", section = "beasts", note = { "A basilisk can pass for a stretch of broken rock until it moves. Its low body and thick hide suit the dry hills of Stranglethorn and the southern deserts; the crystals on some older specimens make the resemblance rather convincing.", "The gaze is the difficulty. These lizards can leave a living opponent rigid as stone, so the usual naturalist's business of taking a closer look becomes an awkward negotiation. There is much to admire in a basilisk, provided it is looking elsewhere." } },
    { id = "kodos", title = "Kodos", section = "beasts", note = { "Kodo herds give the open plains a slow, heavy rhythm. The tauren travel and fight beside these great beasts, and a loaded kodo is a familiar sight wherever the Horde has a long road to cover.", "Desolace holds a stranger gathering: the Kodo Graveyard, where aged animals come to die among the bones of their kind. The living herds are impressive, but those immense remains give a different measure of them. A creature so much a part of a moving caravan can leave a very still place behind." } },
    { id = "rams-and-goats", title = "Rams and Goats", section = "beasts", note = { "A ram looks entirely at home on ground that makes a dwarf consider the quality of his boots. Thick fleece and curved horns are familiar throughout Khaz Modan, and the animals ridden out of Ironforge have wild kin in the same mountains.", "The Stormpike also turn to rams in Alterac Valley. Between a mountain path and a battlefield, there are plenty of demands on a mount's footing. The ram approaches both with the expression of an animal that has already found the ground satisfactory." } },
    { id = "sharks-and-fish", title = "Sharks and Fish", section = "beasts", note = { "The surface of a lake tells very little of its inhabitants. Loch Modan has its frenzies; the coasts have threshers and sharks large enough to make the view from a boat especially welcome.", "These are the fish an angler meets at inconveniently close quarters. A fin in open water is only a fragment of the creature beneath it, and a shoal can turn a quiet pool into sudden movement. The book of life below the surface is a large one; this page covers its more toothsome passages." } },
    { id = "thunder-lizards", title = "Thunder Lizards", section = "beasts", note = { "A thunder lizard carries the surprise of a storm in a heavy, four-footed body. The thunderheads of the Barrens and the great beasts of Desolace can look like ordinary grazing animals until lightning makes the distinction plain.", "Their bulk is impressive enough without that addition. The smaller cliff stormers of Stonetalon have the same unsettling association with thunder. A clear sky over the pass is no guarantee of a quiet crossing." } },
    { id = "great-saurians", title = "Devilsaurs and the Beasts of Un'Goro", section = "beasts", note = { "Un'Goro has room for creatures that would make most other forests seem cramped. Devilsaurs stride above the undergrowth, stegodons carry great plates along their backs, and pterrordaxes circle over the crater rim. A diemetradon by the hot springs can look almost modest in such company.", "The Marshal expedition has given these beasts names and a place in its reports. The crater gives them the rest: dense growth, steaming ground, and room enough for a devilsaur to disappear behind the next stand of trees. Surveying it is a considerable undertaking." } },
    { id = "stags-and-steeds", title = "Stags, Steeds and Grazers", section = "beasts", note = { "Zhevras and giraffes belong to the broad view of the Barrens, while the stags of Ashenvale appear between the trunks of old trees. Their different outlines help a traveller read the country before any signpost does.", "Hunters prize their meat and hides, but Ogtinc of Azshara has another interest in the mosshoof coursers. He sees a confident animal's spirit in their unbroken antlers, and asks for a perfect pair. The impressive crown is also the courser's means of defending itself, which makes an intact specimen difficult to obtain." } },
    { id = "snakes", title = "Snakes", section = "beasts", note = { "A snake can occupy very little of a traveller's attention until it crosses the path. Its body gives almost no clue to its length while coiled, and a lifted head makes a modest patch of ground seem thoroughly claimed.", "The serpents of the Wailing Caverns have been changed by the nightmare there. In Zul'Gurub, serpents have a place in the blood god's worship. Both settings give the naturalist more to consider than scales and venom, though those remain quite sufficient subjects." } },
    { id = "chimaeras", title = "Chimaeras", section = "beasts", note = { "Two heads on one winged body make a chimaera unmistakable, even before its breath strikes. The night elves have fought beside these creatures, whose strength and corrosive attack are formidable against stone as well as flesh.", "Winterspring has a pale, shaggy kind suited to the snow. Off Feralas, the Isle of Dread shelters the enormous chimaeroks. On a map it is a small island; a chimaerok gives a traveller ample reason to consider how much of it remains between beast and shore." } },
    { id = "hydras", title = "Hydras", section = "beasts", note = { "A hydra announces itself several heads at a time. The long necks rise from coastal water or a cavern pool, making it difficult to decide which pair of eyes deserves attention first.", "The Mystlash haunt Kalimdor's shores, while other hydras dwell deep in Maraudon. Gahz'rilla has a sacred pool in Zul'Farrak and the worship of the Sandfury. Most creatures in this book must make do with a feeding ground; that one has acquired a congregation." } },
    { id = "worms-and-grubs", title = "Worms and Grubs", section = "beasts", note = { "Much of the world's work goes on beneath its surface. Grubs move through the rot of the Plaguelands, while larger burrowers occupy sand and stone. What looks like empty ground may be full of life.", "The rock worms of deep places bring the subject to a prospector's attention with unusual force. A creature that belongs comfortably inside the earth is an awkward neighbour for anyone trying to make a tunnel through it. The rock, it seems, was not vacant." } },
    { id = "insects", title = "Insects", section = "beasts", note = { "Not every large insect belongs to a silithid hive. Beetles and scarabs inhabit the deserts and old ruins in their own right, though their size sometimes makes a traveller reach for a weapon before a notebook.", "In Zul'Farrak, scarabs move among the Sandfury's stonework and burial places. Against a temple wall they seem a small detail; gathered at one's boots, they command a good deal more attention." } },
    { id = "birds", title = "Birds of the High Places", section = "beasts", note = { "Look up from a mountain pass and the wings above it may belong to a hippogryph, a wyvern or a gryphon. Travellers put all three in much the same category. The antlers, the stinging tails and the hooked beaks suggest that a naturalist should take a little more trouble.", "Hippogryphs bear night elf riders, gryphons are familiar companions to the Wildhammer, and the Horde has its wind riders. Beyond the roosts and aeries, their wild kin fill the same skies. A saddle is a considerable achievement on any creature that can simply fly away." } },
    { id = "yetis", title = "Yetis", section = "beasts", note = { "Yetis occupy mountain caves from Alterac to Winterspring, with a shaggy kind in the heights of Feralas as well. Their broad bodies and heavy coats give even a large cavern the appearance of cramped lodgings.", "Their horns have attracted Umi Rumplesnicker's attention in Everlook. She needs a perfect pair for the mechanical yeti she is building to frighten her friends. The living yetis are inconveniently attached to the parts." } },
    { id = "wendigos", title = "Wendigos", section = "beasts", note = { "The wendigos of Dun Morogh inhabit snowy caves such as the Grizzled Den, where white fur disappears against the snow. The size of their hands is less easily overlooked.", "Their hides and manes are familiar subjects of local hunting work. To a young dwarf, the hills beyond a settlement can seem an extension of home; a wendigo at a cave mouth gives those hills a rather different scale. Not every large shape in the snow is another mountaineer." } },
    { id = "other-beasts", title = "Other Beasts", section = "beasts", note = { "There are beasts for which a neat family heading would promise more than the evidence allows. An unusual shape, a solitary specimen, or a creature known chiefly by the name on a hunter's commission may find its place here.", "A broad catalogue is useful until it hides the animal inside it. These records leave room for the individual: where it was met, what it looked like, and what distinguishes it from the last supposedly unique monster." } },
    { id = "black-dragonflight", title = "The Black Dragonflight", section = "dragonkin", note = { "Black dragonkin inhabit country marked by fire and broken stone. Whelps appear in Redridge and the Badlands; greater servants guard Nefarian's fortress in Blackrock Spire and Onyxia's lair in Dustwallow.", "Deathwing's betrayal hangs over the flight, while his children pursue ambitions of their own. Nefarian's experiments bring dragons of different colours into the same terrible work. A naturalist accustomed to describing the distinctions between flights finds very little comfort in what Nefarian is trying to make of them." } },
    { id = "green-dragonflight", title = "The Green Dragonflight", section = "dragonkin", note = { "Ysera's green flight guards the Emerald Dream, but the Nightmare has reached some of its own guardians. The dragonkin at the great portals of Ashenvale, Feralas, the Hinterlands and Duskwood make that danger visible in the waking world.", "Eranikus's shade haunts the Sunken Temple, and other powerful dragons have emerged changed from the Dream. The great trees around the portals remain beautiful. That is part of what makes the corruption so disturbing: the entrance to a place of life has acquired such troubled guardians." } },
    { id = "blue-dragonflight", title = "The Blue Dragonflight", section = "dragonkin", note = { "Blue dragonkin guard arcane places: the old ruins of Azshara and the icy halls of Mazthoril. Malygos's flight has a long responsibility for magic, which gives a mortal rummaging among such treasures an awkward position from the outset.", "Azuregos watches Azshara with a distinctly personal attitude toward visitors. His dealings over an old magical ledger reveal a sense of humour. Ancient duty has not prevented him from finding an adventurer's errands amusing." } },
    { id = "red-dragonflight", title = "The Red Dragonflight", section = "dragonkin", note = { "Red whelps still inhabit the Wetlands, where the larger members of Alexstrasza's flight guard Grim Batol. The mountain once held their queen captive under the Dragonmaw orcs, who used her offspring in the Second War.", "Her freedom ended that captivity without making Grim Batol a welcoming place. Red dragonkin now keep its approaches against outsiders. For a flight charged with protecting life, those guarded gates carry a long and bitter memory." } },
    { id = "faerie-dragons", title = "Faerie Dragons", section = "dragonkin", note = { "A faerie dragon brings bright wings and a small, quick body into the old forests of Kalimdor. Despite the name and its place on this page, it is not a little member of one of the great dragonflights.", "These creatures have ties to the Emerald Dream and a peculiar relationship with magic. The night elves know them as forest allies; the deviate kind in the Wailing Caverns belongs to a much less fortunate setting. Colour alone gives a poor account of what has happened to a creature there." } },
    { id = "bronze-dragonflight", title = "The Bronze Dragonflight", section = "dragonkin", note = { "The Caverns of Time open beneath Tanaris, though the bronze flight's business reaches far beyond that stretch of desert. Nozdormu's dragons guard time itself, an undertaking for which the League possesses no satisfactory measuring instruments.", "Their part in sealing Ahn'Qiraj belongs to recorded history. Anachronos still watches the desert from outside the caverns, an immense living witness to a war whose other traces lie beneath the sand." } },
    { id = "other-dragonkin", title = "Other Dragonkin", section = "dragonkin", note = { "A dragon's colour usually offers a beginning to its history. It is less helpful with an unfamiliar specimen, or with the mixed dragonkin produced by Nefarian's experiments in Blackrock Spire.", "Such creatures are recorded here until there is sound reason to place them elsewhere. A tidy catalogue should not conceal a difficult identification, particularly when the creature in question is large enough to object to the delay." } },
    { id = "satyrs", title = "Satyrs", section = "demons", note = { "A satyr camp is a wound in an old forest. Horned figures move among sickened trees, and the night elves who oppose them are fighting creatures whose history began among their own people.", "Xavius, Queen Azshara's counsellor, was the first of the satyrs, remade by Sargeras during the ancient war. Their kind still serve corruption in Ashenvale and Felwood. Ten thousand years have passed, yet the forest is still losing ground around their camps." } },
    { id = "burning-legion", title = "The Burning Legion", section = "demons", note = { "The Legion's presence changes a landscape. In Felwood the trees bear the damage; in the Blasted Lands, demons occupy ground around the Dark Portal. Mannoroc Coven and Demon Fall Canyon have their own surviving reminders of invasion.", "Its ranks differ enormously: a felhound hunts magic, an infernal brings stone and flame, and an imp can make a remarkable amount of trouble in very little space. The wars that brought them here have ended, but a map of their remaining camps is far from empty." } },
    { id = "fire-elementals", title = "Fire Elementals", section = "elementals", note = { "Living flame walks the scorched country around Blackrock Mountain and the slopes of Un'Goro's volcano. A fire elemental gives the familiar movement of a blaze a direction and a purpose of its own.", "Ragnaros rules the deepest fires beneath Blackrock, with servants throughout his domain. Elsewhere, shamans and summoners call flame into other settings. The element remains recognisable, though its presence alone does not tell a traveller whose command, if anyone's, it is obeying." } },
    { id = "water-elementals", title = "Water Elementals", section = "elementals", note = { "A water elemental gives a spring or pool a moving inhabitant made of its own substance. The befouled elementals of Ashenvale carry their woodland's corruption into that familiar shape.", "Off Azshara, the Hydraxian Waterlords have a very different purpose, opposing Ragnaros and his servants. Mages summon water elementals as well. A wave rising into a body is a striking sight, but it takes something of the place and its history to explain why it is there." } },
    { id = "earth-elementals", title = "Earth Elementals", section = "elementals", note = { "Earth elementals bring the hillside with them: heavy shapes of rock moving through the Badlands, obsidian bodies in the scorched lands around Blackrock. The distinction between a boulder and an inhabitant can be a brief one.", "Uldaman also contains stone keepers, constructs guarding a made place rather than wild spirits roaming open ground. To the League that difference is considerable. A rock elemental may be a feature of the landscape; a stone guardian is evidence that somebody had something to protect." } },
    { id = "air-elementals", title = "Air Elementals", section = "elementals", note = { "Dust devils cross open fields, while greater whirlwinds take shape in Desolace and Silithus. An air elemental is easiest to see in what it gathers around itself: dust, cloud and the loose things a traveller thought securely packed.", "The Twilight's Hammer summons elemental powers in the southern desert. A storm encountered there may have more behind it than unsettled weather. The wind has acquired a shape, and somebody may have invited it." } },
    { id = "living-plants", title = "Living Plants and Ancients", section = "elementals", note = { "A forest can move without a breeze. Treants and ancients give the night elves' woods their great walking shapes, while lashers and creepers occupy ground much nearer a traveller's boots.", "Some defend a living woodland; others have been changed by corruption. The timberlings of Teldrassil and the growth within Dire Maul deserve different accounts, even when both make a path difficult to cross.", "The swamp has its own forms of moving vegetation and mud. Roots, branches and a familiar green colour are only the beginning of identifying what has risen out of it." } },
    { id = "blighted-elementals", title = "Blighted Elementals", section = "elementals", note = { "The tar pits of Un'Goro and the poisoned ground of Felwood both produce moving shapes, but they should not be given the same history merely because neither is pleasant to touch. Tar beasts belong to the crater; toxic horrors belong to a wounded forest.", "Gnomeregan's fallout and the Plaguelands' blight add other examples to this troubled page. Each bears something of the place that formed it. Their differences matter: what rises from the ground can tell a naturalist what has happened to the ground itself." } },
    { id = "oozes", title = "Oozes and Slimes", section = "elementals", note = { "An ooze has very little shape to help a naturalist describe it. Colour and consistency have to do much of the work: the sludges of a marsh, the strange remains of Gnomeregan's disaster, the moving filth of poisoned water.", "Some leave the remains of what they have swallowed, an unappealing but useful record of their surroundings. They are easily overlooked beside a great beast or a walking tree. A patch of slime moving against the slope has its own claim on the notebook." } },
    { id = "other-elementals", title = "Other Elementals", section = "elementals", note = { "The familiar divisions of earth, air, fire and water do not settle every encounter. Some animated beings and unusual elemental shapes reach this page without a clear place among the others.", "Their setting often supplies the best beginning: a summoner's chamber, an ancient hall, or a strange patch of open country. The record can preserve those particulars even where the nature of the inhabitant remains unsettled." } },
    { id = "scourge", title = "The Scourge", section = "undead", note = { "The Scourge turns a population into an army: skeletons, ghouls, plague victims and stitched abominations fill the roads and ruins of Lordaeron. Its necromancers add new soldiers wherever bodies can be found.", "Scholomance and Stratholme are great centres of that work, while Razorfen Downs shows how far its influence reaches. The dead need neither harvest nor rest, and the country they occupy steadily loses the life that once supported it.", "Among the bones and ruined clothes are the remains of ordinary inhabitants. The army has no use for their old occupations, though a field journal can still acknowledge them." } },
    { id = "restless-spirits", title = "Ghosts and Restless Spirits", section = "undead", note = { "Not every ghost in Azeroth serves the Scourge. Some are spirits who never found rest: the Highborne who haunt their ruined towers in Darkshore and Azshara, the drowned and the murdered, the warriors who fell far from home and wander still.", "Some are only sad. Some are angry, and the anger is all that is left of them. A few will speak, if you listen.", "The League records them with care. They are, after all, the oldest witnesses we have." } },
    { id = "other-undead", title = "Other Undead", section = "undead", note = { "Lordaeron's plague does not explain every walking corpse. Duskwood has graves disturbed by other hands, and old curses or a necromancer's work can leave the dead moving far from the Scourge's armies.", "A name can be especially valuable here. The remains may have outlasted the explanation, while a village record or a surviving relative still preserves it. The creature in the graveyard and the person in the account are sometimes the same subject, approached from opposite ends of a story." } },
    { id = "giants", title = "Giants", section = "giants", note = { "Sea giants stride the coasts of Kalimdor, and great cliff walkers occupy the heights of Azshara and Feralas. Against a distant headland their size can be difficult to judge; a tree or a ruined column beside them supplies the missing measure.", "Accounts connect the world's giants with its ancient shaping. The League still has much to establish about the different kinds. For a surveyor, even their tracks are substantial features of the ground, and a living specimen can interrupt a very wide view." } },
    { id = "machines", title = "Golems and Machines", section = "machines", note = { "A harvest golem among Westfall's fields belongs to a different sort of nature. Shredders in Stonetalon, war machines in Gnomeregan and the Dark Irons' constructs all began with a workshop, whatever has become of their instructions since.", "Their makers' intentions can survive in the design: cutting arms, harvesting claws, a cannon placed where an animal would have a head. The machine need not explain itself. An observer can often read its purpose in the tools attached to it." } },
    { id = "kobolds", title = "Kobolds", section = "peoples", note = { "A light in an abandoned mine often belongs to a kobold. Their candles mark the tunnels of Elwynn and Westfall, where narrow passages allow a small digger to make a large nuisance of itself.", "The familiar protest, \"You no take candle!\", is quite clear on the subject most urgently at hand. Beyond that, the candle tells a practical story: somebody intends to work and live in the dark. To the miner coming back for his claim, the tunnel is occupied; to the kobold, the miner is an intruder." } },
    { id = "gnolls", title = "Gnolls", section = "peoples", note = { "Gnoll camps cluster around mines, fields and poorly guarded roads. Riverpaw tents in Elwynn and Westfall, Mosshide huts in the Wetlands, and Woodpaw camps in Feralas have much the same practical advantage: other people's provisions within reach.", "Their packs have leaders, spellcasters and raiders, and can put a settlement under real pressure. Hogger's reputation has travelled far beyond his patch of Elwynn. It is an unusual distinction for a gnoll, though the people paying his bounty would gladly see it ended." } },
    { id = "murlocs", title = "Murlocs", section = "peoples", note = { "Murloc villages leave a recognisable mark on a shore: low huts, fishing nets and a great deal of noise when a stranger approaches. Their tools and settlements deserve more attention than the usual accounts of a gurgling charge give them.", "They defend those villages together, which explains why a fight begun with one can spread along a beach so quickly. Their speech is difficult for most travellers to understand. That is a difficulty in translation, not evidence that there is nothing being said." } },
    { id = "troggs", title = "Troggs", section = "peoples", note = { "Troggs have come out of the deep places into Dun Morogh, Loch Modan and Gnomeregan. Their strength is plain enough; their connection to dwarven history was a much less welcome discovery.", "The records in Uldaman describe an earlier shaping of stone into life, followed by the earthen from whom dwarves descend. Those records make the trogg a subject for the League as well as an enemy at the dig.", "So the same excavation can produce an ancestor's history and a very angry inhabitant. Archaeology seldom arranges its subjects conveniently." } },
    { id = "ogres", title = "Ogres", section = "peoples", note = { "Ogres came through the Dark Portal with the Horde, then scattered into clans across Azeroth. A ruined tower or a mountain cave may now house Boulderfist, Crushridge, Dustbelcher or another clan whose name has become a local warning.", "Their size is the first thing noticed, but ogre magi make poor subjects for the usual jokes about ogre intelligence. Two heads can carry a formidable command of magic.", "The Stonemaul of Dustwallow have joined the Horde. Elsewhere, a clan's loyalties have to be learned separately; a familiar outline is no introduction." } },
    { id = "defias", title = "The Defias Brotherhood", section = "peoples", note = { "A red mask can mean a cutpurse on an Elwynn road or a craftsman at work beneath the Deadmines. The Defias Brotherhood grew out of the Stonemasons' unpaid labour rebuilding Stormwind, and Edwin VanCleef carried that grievance into Westfall.", "The farms now suffer for a quarrel their owners did not settle. Under Moonbrook, the Brotherhood has organised something far larger than roadside robbery: workshops, hired muscle and a ship. The masons' skill has survived; the city it was meant to serve has become their target." } },
    { id = "syndicate", title = "The Syndicate", section = "peoples", note = { "The Syndicate occupies the remains of Alterac's power: ruined settlements in the mountains, positions at Durnholde and a foothold in Stromgarde. Dispossessed nobles and hired criminals make an uneasy replacement for a kingdom.", "Their camps still have officers and ambitions, even when their work amounts to robbery. A fallen lord can retain his title long after losing the means to live by it. In the foothills, the passing traveller may be asked to make up the difference." } },
    { id = "scarlet-crusade", title = "The Scarlet Crusade", section = "peoples", note = { "The Scarlet Crusade's red banners mark some of Lordaeron's strongest surviving human positions: the monastery, Hearthglen, Tyr's Hand and part of Stratholme. Priests, paladins and soldiers hold those walls against the undead.", "Their suspicion reaches well beyond the Scourge. Outsiders may be treated as carriers of plague or as enemies in disguise, and the Forsaken have no place in their idea of a restored kingdom. A traveller can find living defenders behind the barricades without finding sanctuary." } },
    { id = "cult-of-the-damned", title = "The Cult of the Damned", section = "peoples", note = { "Among the Scourge's dead stand people who are still alive. The Cult of the Damned supplies necromancers, acolytes and willing hands to an army that would otherwise have to manufacture all of its recruits.", "The Scholomance beneath Caer Darrow gives those arts a school, with lessons conducted among the remains of Lordaeron. Elsewhere the cult tends plague cauldrons and raises the fallen. A living scholar at a desk ought to be a reassuring sight. Here, the subject of study makes all the difference." } },
    { id = "dark-iron-dwarves", title = "Dark Iron Dwarves", section = "peoples", note = { "Dark Iron work is unmistakably dwarven: deep mines, heavy fortifications and machinery built to outlast its makers. The clan's stronghold beneath Blackrock Mountain is a city as well as a fortress, with forges, an arena and an emperor's court.", "The War of the Three Hammers left them enemies of Ironforge; Thaurissan's summoning left them subject to Ragnaros. Their agents now work far beyond the mountain, in quarries and camps across Khaz Modan.", "Black powder and fine masonry are familiar things to find in another dwarf's hands. It is the direction of the cannon that makes this a difficult page." } },
    { id = "blackrock", title = "The Blackrock Clan", section = "peoples", note = { "The Blackrock orcs hold the roads around their mountain as well as the halls within it. From the Burning Steppes their raiders reach Redridge, where Stonewatch Keep gives the people of Lakeshire a standing reminder of the clan's strength.", "Rend Blackhand claims the title of Warchief, though his followers serve beneath Nefarian's wings. They carry the weapons and ambitions of the old Horde into a world where Thrall is trying to build another. The difference is visible well before a traveller reaches the Spire." } },
    { id = "dragonmaw", title = "The Dragonmaw Clan", section = "peoples", note = { "The Dragonmaw once brought red dragons to war by keeping Alexstrasza captive at Grim Batol. The queen's freedom broke that power, but the clan still has camps in the Wetlands, where its standards are a familiar danger along the roads.", "Their raids belong to the remnant wars of the old Horde. Grim Batol itself is guarded by the red flight now, an imposing reminder that the clan once held a much greater captive than any prisoner its remaining warriors could take." } },
    { id = "burning-blade", title = "The Burning Blade", section = "peoples", note = { "The Burning Blade's name survives on the lips of warlocks and demon worshippers. Its cultists occupy caves in Durotar and gather in Desolace; beneath Orgrimmar, Ragefire Chasm brings that allegiance uncomfortably close to the Horde's new home.", "Thrall's people have fought to escape the Legion's rule. These cultists invite its servants back, with summoning circles in the very country the freed orcs have settled. For a people recovering an older way of life, they are a particularly bitter neighbour." } },
    { id = "twilights-hammer", title = "The Twilight's Hammer", section = "peoples", note = { "The Twilight's Hammer has grown from an orc clan into a cult with followers of many peoples. Its camps gather around old powers: in Blackfathom Deeps, near dark idols, and across the elemental country of Silithus.", "The cult's writings look forward to the end of the world, and its summoners work to hasten it. Robes and scholarly trappings can give the camps an appearance of study. The summoned elemental lords explain what the studies are for." } },
    { id = "venture-company", title = "The Venture Company", section = "peoples", note = { "The Venture Company's works are often visible before its workers: a stripped hillside in Stonetalon, oil in the Barrens, a mine cut into Mulgore's cliffs. Shredders, drills and hired guards follow the claim.", "Goblins organise much of the work, though the labour and muscle come from several peoples. To the settlements nearby, the company is less a distant concern than a growing hole or a retreating tree line. Its accounts may put a value on the timber; the empty hillside is harder to price." } },
    { id = "pirates", title = "Pirates", section = "peoples", note = { "A pirate camp has much of a port about it: ships, stores and sailors with work to do. The difference becomes apparent when a Bloodsail ship closes on Booty Bay, or Southsea crews lay claim to another cargo.", "Their strongholds dot the warm coasts, from the Merchant Coast to Tanaris. Goblin trade has made those waters busy enough to support both merchants and the people who rob them. From a distant headland the sails can look much alike." } },
    { id = "naga", title = "Naga", section = "peoples", note = { "The naga occupy drowned places that were once part of the night elves' world: the Zoram Strand, the ruins of Azshara and the coast of Darkshore. Their serpentine bodies now suit the water that covered the Highborne's old dominion.", "They rose openly after the Third War and have established themselves on many shores since. Sea witches and armed myrmidons make these more than scattered beach camps. Among the broken pillars, they can seem to have returned to a city whose streets only they can still use." } },
    { id = "centaurs", title = "Centaurs", section = "peoples", note = { "Centaur clans occupy the open country of Kalimdor, their villages and warbands spread across the Barrens, Desolace and Thousand Needles. The tauren know them as generations of pursuers. In Desolace, the names Gelkis, Magram and Maraudine mark rival claims as well as different camps.", "A traveller can bargain with some of these clans, though friendship with one is liable to cost the friendship of another. Their shamans speak of the earth, and Theradras has her worshippers among them. There is more here than a raid seen from the road.", "Their ancestry leads back to Theradras and Zaetar, the son of Cenarius whose own children killed him. Maraudon holds that family history in a particularly unhappy form." } },
    { id = "quilboar", title = "Quilboar", section = "peoples", note = { "The immense thorns of the Barrens are a homeland to the quilboar. Their traditions name Agamaggan as their ancestor, and the fallen demigod's presence belongs to the land as well as to their rites.", "Razormane, Bristleback and Razorfen camps defend that country against tauren, centaurs and the new Horde. Their shamans give the thorny settlements another kind of strength. At Razorfen Downs, dealings with the Scourge have carried the Death's Head tribe into a darker allegiance.", "An outsider sees a wall of brambles. Beyond it are homes, rival tribes and a history older than the road passing by." } },
    { id = "harpies", title = "Harpies", section = "peoples", note = { "Harpies make their homes above the approaches to other people's settlements. The Dustwind roosts of Durotar, the Windfury heights of Mulgore and the Witchwing nests of the Barrens all give wings the advantage over a caravan.", "Their talons are only part of the danger; storm witches add spells to the shrieking of a disturbed flock. A nest high on a cliff is a difficult place to reach with questions. Much of the League's knowledge of harpies has therefore been gathered from the ground below." } },
    { id = "furbolgs", title = "Furbolgs", section = "peoples", note = { "Furbolg villages belong to the old forests of Kalimdor. Totems, shelters and shamans give them a place among the forest's peoples, though a traveller arriving at a corrupted camp may see only its violence.", "The Gnarlpine, Blackwood, Deadwood and Winterfall have all suffered terrible changes. The Timbermaw have resisted that fate and still guard their tunnels between Felwood, Moonglade and Winterspring. Their distrust of strangers has ample cause.", "Azshara's Blackmaw Hold belongs to another tribe. Corruption has taken root there too; the Timbermaw of Felwood should not bear the blame for what lies behind its stone gate." } },
    { id = "grimtotem", title = "The Grimtotem", section = "peoples", note = { "Grimtotem camps occupy commanding ground: Darkcloud Pinnacle above Thousand Needles, a compound in Feralas, and holdings farther across Kalimdor. Their warriors and shamans have the strength of other tauren, directed against neighbours who often share their ancestry.", "Magatha Grimtotem has a place among Thunder Bluff's elders, even while her tribe's ambitions set it against Cairne's course. The familiar totems and tents can make a hostile camp look deceptively like a refuge from the road." } },
    { id = "worgen", title = "Worgen", section = "peoples", note = { "Arugal called worgen into Silverpine to fight the Scourge and lost control of what he had summoned. Shadowfang Keep is now their stronghold, while nearby Pyrewood bears a curse that changes its people after nightfall.", "The Nightbane of Duskwood belong to another troubled account, entangled with the Scythe of Elune and the summons described by Velinde Starsong. Their presence cannot be explained simply by pointing toward Arugal's tower.", "Both places have acquired the same terrible outline among the trees: a wolf's head above an upright body. The histories behind it have to be followed separately." } },
    { id = "forest-trolls", title = "Forest Trolls", section = "peoples", note = { "The Witherbark, Vilebranch and Mossflayer occupy forests layered with the remains of older troll dominion. Jintha'Alor is still a formidable temple-city, its terraces climbing the Hinterlands rather than sinking quietly into them.", "The Amani fought Quel'Thalas long before the present human kingdoms took their shape. That long rivalry survives among tribes whose fortunes now differ greatly. The Revantusk trade with the Horde on the Hinterlands coast, while their neighbours hold their own ground inland.", "Green skin and tusks identify a forest troll readily enough. They do not tell a traveller which welcome to expect." } },
    { id = "jungle-trolls", title = "Jungle Trolls", section = "peoples", note = { "Stranglethorn's troll ruins are inhabited history. Bloodscalp and Skullsplitter tribes fight among the old stones, while Zul'Gurub remains a centre of Gurubashi power. Its high priests have brought Hakkar back into the world.", "The Atal'ai carry the blood god's worship into the Sunken Temple as well. Other jungle trolls have taken another course: the Darkspear belong to Thrall's Horde, and Yojamba Isle shelters Zandalar's effort against Hakkar. An old empire has left many heirs, with very different purposes." } },
    { id = "sand-trolls", title = "Sand Trolls", section = "peoples", note = { "Zul'Farrak still rises above the sand as a city, despite all the ruin around it. The Sandfury defend its terraces and sacred pools against a desert increasingly crowded with goblins, bandits and adventurers.", "Gahz'rilla is worshipped there, and the tombs have guardians that did not remain dead. The city is poor ground for treating every old stone as an abandoned relic. Its builders' descendants are quite capable of disputing a visitor's claim to one." } },
    { id = "ice-trolls", title = "Ice Trolls", section = "peoples", note = { "The Frostmane know Dun Morogh as a homeland rather than a road to Ironforge. Their hold west of Kharanos and their camps in the snow remain close to the dwarven settlements that have driven them from much of the valley.", "Headhunters, seers and shadowcasters defend what they still possess. For a young dwarf these are often the first troll enemies met; for the Frostmane, the dwarf is another arrival from the city above. The same snowy pass carries two very different accounts of who belongs there." } },
    { id = "makrura", title = "Makrura", section = "peoples", note = { "Makrura occupy Kalimdor's shallows with a presence quite different from the crabs beside them. The upright bodies, grasping claws and guarded colonies belong to a people, however unfamiliar their speech and shape may be.", "Durotar's shore gives many young orcs their first encounter with them. Larger colonies lie farther down the coast. A beach offers little cover to a traveller approaching from land, while the water behind a makrura settlement need not be the limit of its inhabitants." } },
    { id = "wildkin", title = "Wildkin", section = "peoples", note = { "A wildkin has the bulk of a bear beneath an owl's face and feathers, a combination that deserves a quiet moment of attention. The night elves hold these creatures sacred to Elune.", "Moonkin live in Darkshore, and owlbeasts occupy the Hinterlands and Winterspring. Their names and temperaments vary, but the great round eyes remain distinctive. A forest containing one can feel watched in a way that has little to do with a hunter's ambush." } },
    { id = "leper-gnomes", title = "Leper Gnomes", section = "peoples", note = { "Gnomeregan's fall did not send every survivor to Ironforge. Radiation left some of those within the city changed in body and mind, and the leper gnomes still inhabit its approaches and machinery-filled halls.", "Their green skin makes the harm visible at once. The familiar gnomish clothes and tools make its meaning harder to put aside. For the exiles, the old city contains neighbours as well as the things that drove them out." } },
    { id = "earthen", title = "The Earthen", section = "peoples", note = { "The earthen are beings of living stone, made by the titans to shape the deep places of the world, and in Uldaman some of them still walk the halls of the titans' vault, guarding it as they were made to.", "The platinum discs in that vault say the dwarves descend from them. These are, in the plainest sense, my ancestors, and they will try to kill you.", "I record them with a respect I cannot quite explain, and a caution I can." } },
    { id = "shadow-council", title = "The Shadow Council", section = "peoples", note = { "The Shadow Council helped bind the old Horde to the Legion. Its surviving influence now appears in places such as Jaedenar, where cultists and demons occupy the same corrupted ground.", "Thrall's Horde has rejected those masters, but the summoning circles remain. Around them gather practitioners from more than one people, pursuing arts whose cost is already written across Felwood. The blackened trees are a useful accompaniment to any promises made inside the camp." } },
    { id = "servants-of-the-firelord", title = "Servants of the Firelord", section = "peoples", note = { "The flamewakers of the Molten Core are unmistakable servants of Ragnaros: armed figures with serpentine lower bodies, at home among the fires beneath Blackrock Mountain. Lucifron, Gehennas, Shazzrah and their kind guard the approaches to the Firelord.", "Here, the mountain's heat is part of an inhabited realm. What a dwarf might regard as an impossible place to build contains guards, commanders and a master's seat. The absence of comfortable ground is entirely the visitor's problem." } },
    { id = "lost-ones", title = "The Lost Ones", section = "peoples", note = { "The draenei at the Harborage are refugees from Draenor, the world from which the orcs came. The Lost Ones at Fallow Sanctuary share that origin, though their violent isolation makes the connection less apparent to a traveller crossing the swamp.", "Magtoor and his companions offer help where they can, among people who scarcely know what to make of them. Their presence gives the Lost Ones' camp a sadder context: this is another people scattered far from home, with some of its own no longer able to find refuge among the rest." } },
    { id = "goblins", title = "Goblins", section = "peoples", note = { "The goblins recorded here are encountered across a workshop floor or a battlefield rather than a shop counter. VanCleef has engineers in the Deadmines, and dangerous inventions turn up wherever their makers find room to work.", "A shredder or a hired guard tells something about the resources behind a small goblin camp. Much of the fighting may be done by something the engineer has built, bought or persuaded to stand in front. The inventor's stature gives a poor measure of the size of the enterprise." } },
    { id = "hostile-elves", title = "Hostile Elves", section = "peoples", note = { "An elven expedition among the ruins may be seeking the same things as the League: an inscription, a relic, a surviving piece of ancient craft. In Azshara, the blood elves' pursuit of lost arcane power makes that common interest a poor guarantee of welcome.", "Dire Maul has its own dangerous students of magic, Lethtendris among them. The old cities still contain power worth seeking, and the people who reach it do not always leave room for a second scholar." } },
    { id = "druids-of-the-fang", title = "The Druids of the Fang", section = "peoples", note = { "Naralex entered the Wailing Caverns hoping to restore the Barrens through the Emerald Dream. He still sleeps there, and the nightmare that caught him has changed both the cavern's beasts and his disciples.", "The Druids of the Fang bear serpent names and take serpent shapes: Cobrahn, Anacondra, Pythas and Serpentis. Their rites occupy caves that were meant to be the beginning of a greener land. Water and growth are plentiful below the Barrens; the trouble is what has grown with them." } },
    { id = "bandits-and-mercenaries", title = "Bandits and Mercenaries", section = "peoples", note = { "A wanted poster makes an outlaw look like a solitary problem. The Wastewander camps of Tanaris and Kurzen's compound in Stranglethorn suggest otherwise: guards, supplies and an organisation that survives the loss of any one bandit.", "Kurzen's followers were soldiers before the jungle took its hold on their expedition. Others work for pay or prey on the roads. Their reasons differ, and the banners may be absent, but a guarded camp has much in common with the army it once belonged to." } },
    { id = "other-peoples", title = "Other Humanoids", section = "peoples", note = { "Some foes are best recorded by the place and company in which they were met. A lone outlaw, a dungeon's guard and a renegade magician may share a race without sharing any cause.", "These pages keep their encounters together without inventing a banner for them. A name, a weapon and a camp are modest beginnings for an account, but they are better than allowing an unfamiliar person to disappear into the word \"enemy\"." } },
    { id = "silithid", title = "Silithid and Qiraji", section = "oddities", note = { "Silithid hives change the shape of the southern deserts. Mounds rise above tunnels occupied by wasps, workers and great armoured reavers; the surface gives only a partial view of the population below.", "The Qiraji of Ahn'Qiraj command these swarms. A thousand years ago, the War of the Shifting Sands ended with the armies sealed behind the Scarab Wall by night elves and dragons.", "The hives beyond that wall make the old war a present concern. A low mound on the horizon can mark a much larger claim beneath the sand." } },
    { id = "oddities", title = "Strange Creatures", section = "oddities", note = { "Some encounters leave the headings of a natural history looking inadequate. A singular monster, a strange dungeon inhabitant or a creature honoured by a local cult may have no useful kin elsewhere in the book.", "This page keeps the particular encounter intact while its place in the wider account remains uncertain. There is room in a field journal for an unanswered question, especially one that has just walked out of a lake." } },
